 869: static int velawear_start(velawear_agent_t *agent)
 870: {
 871:   int ret;
 872: 
 873:   /* The main loop owns event queue consumption.  Do not start a second
 874:    * consumer thread for the same mqueue. */
 875: 
 876:   /* Start action manager thread. */
 877: 
 878:   ret = action_manager_start(&agent->actions);
 879:   if (ret < 0)
 880:     {
 881:       syslog(LOG_ERR, "[VelaWear] Action manager start failed: %d\n", ret);
 882:       return ret;
 883:     }
 884: 
 885:   /* Decision rules are evaluated synchronously for each event. */
 886: 
 887:   /* Mark agent as running before starting the sensor producer. */
 888: 
 889:   agent->running = true;
 890:   ret = velawear_watchdog_start(agent);
 891:   if (ret < 0)
 892:     {
 893:       agent->running = false;
 894:       return ret;
 895:     }
 896: 
 897:   if (agent->audio.initialized)
 898:     {
 899:       ret = audio_sensor_start(&agent->audio, &agent->events);
 900:       if (ret < 0)
 901:         {
 902:           agent->audio_available = false;
 903:           syslog(LOG_WARNING,
 904:                  "[VelaWear] Continuous microphone start failed: %d\n", ret);
 905:         }
 906:     }
 907: 
 908:   if (agent->imu.initialized)
 909:     {
 910:       ret = pthread_create(&agent->imu_thread, NULL,
 911:                            velawear_imu_thread, agent);
 912:       if (ret != 0)
 913:         {
 914:           agent->running = false;
 915:           syslog(LOG_ERR, "[VelaWear] IMU thread start failed: %d\n", ret);
 916:           return VELAWEAR_ERR_IO;
 917:         }
 918:       agent->imu_thread_started = true;
 919:     }
 920:   return VELAWEAR_OK;
 921: }
 922: 
 923: static void velawear_cleanup(velawear_agent_t *agent)
 924: {
 925:   /* Stop subsystems in reverse order */
 926: 
 927:   agent->running = false;
 928:   velawear_watchdog_stop(agent);
 929:   if (agent->imu_thread_started)
 930:     {
 931:       pthread_join(agent->imu_thread, NULL);
 932:       agent->imu_thread_started = false;
 933:     }
 934: 
 935:   audio_sensor_cleanup(&agent->audio);
 936:   velawear_llm_cleanup(&agent->llm);
 937:   velawear_ble_cleanup();
 938:   imu_sensor_cleanup(&agent->imu);
 939:   action_manager_cleanup(&agent->actions);
 940:   event_manager_cleanup(&agent->events);
 941:   decision_engine_cleanup(&agent->engine);
 942:   velawear_buttons_close();
 943:   display_manager_cleanup(&agent->display);
 944:   state_manager_cleanup(&agent->state_mgr);
 945:   velawear_config_cleanup(&agent->config);
 946: }
