 954: static int velawear_event_handler(velawear_event_t *event, void *context)
 955: {
 956:   velawear_agent_t *agent = (velawear_agent_t *)context;
 957:   velawear_state_t state;
 958:   velawear_action_t action;
 959:   int rule_id;
 960:   int ret;
 961: 
 962:   if (event->type == VELAWEAR_EVENT_AUDIO)
 963:     {
 964:       syslog(LOG_INFO,
 965:              "[Audio] event=%s avg_abs=%lu peak_abs=%lu active=%d\n",
 966:              event->data.audio.text,
 967:              (unsigned long)event->data.audio.avg_abs,
 968:              (unsigned long)event->data.audio.peak_abs,
 969:              event->data.audio.active ? 1 : 0);
 970:     }
 971: 
 972:   ret = state_manager_update_from_event(&agent->state_mgr, event);
 973:   if (ret < 0)
 974:     {
 975:       return ret;
 976:     }
 977: 
 978:   state = state_manager_get_state(&agent->state_mgr);
 979:   agent->state = state;
 980:   rule_id = decision_engine_evaluate(&agent->engine, &state, event);
 981: 
 982:   /* Every matched rule produces a traceable action.  Rule-specific handlers
 983:    * can replace this log action later without changing the event pipeline. */
 984:   if (rule_id >= 0 && event->type != VELAWEAR_EVENT_MOTION &&
 985:       event->type != VELAWEAR_EVENT_FALL)
 986:     {
 987:       memset(&action, 0, sizeof(action));
 988:       action.type = VELAWEAR_ACTION_LOG;
 989:       action.priority = event->priority;
 990:       ret = action_manager_execute(&agent->actions, &action);
 991:       if (ret < 0)
 992:         {
 993:           return ret;
 994:         }
 995:     }
 996: 
 997:   /* The action manager worker performs callbacks; wake it after evaluation. */
 998:   return action_manager_process(&agent->actions);
 999: }
