   317	static void velawear_ble_notify_current_status(void)
   318	{
   319	  uint8_t value[3];
   320	  struct bt_conn *conn;
   321	
   322	  pthread_mutex_lock(&g_lock);
   323	  value[0] = (uint8_t)g_motion_type;
   324	  value[1] = g_intensity_percent;
