   339	static int velawear_ble_notify_agent_packet(uint16_t attr_index,
   340	                                            const uint8_t *frame,
   341	                                            uint16_t frame_size)
   342	{
   343	  bool notify_enabled;
   344	  struct bt_conn *notify_conn;
   345	  struct bt_conn *conn;
   346	  int ret;
   347	
   348	  pthread_mutex_lock(&g_lock);
   349	  if (attr_index == VELAWEAR_BLE_AGENT_EVENT_ATTR_INDEX)
   350	    {
   351	      notify_enabled = g_agent_event_notify_enabled;
   352	      notify_conn = g_agent_event_notify_conn;
   353	    }
   354	  else if (attr_index == VELAWEAR_BLE_AGENT_RESULT_ATTR_INDEX)
   355	    {
   356	      notify_enabled = g_agent_result_notify_enabled;
   357	      notify_conn = g_agent_result_notify_conn;
   358	    }
   359	  else
   360	    {
   361	      pthread_mutex_unlock(&g_lock);
   362	      return VELAWEAR_ERR_INVAL;
   363	    }
   364	
   365	  conn = notify_enabled && notify_conn != NULL ? bt_conn_ref(notify_conn) : NULL;
   366	  pthread_mutex_unlock(&g_lock);
   367	  if (conn == NULL)
   368	    {
   369	      return VELAWEAR_OK;
   370	    }
   371	
   372	  ret = bt_gatt_notify(conn, &attr_velawear_svc[attr_index], frame, frame_size);
   373	  bt_conn_unref(conn);
   374	  if (ret < 0)
   375	    {
   376	      syslog(LOG_WARNING, "[BLE] Agent notification failed: %d\n", ret);
   377	      return ret;
   378	    }
   379	
   380	  return VELAWEAR_OK;
   381	}
