   383	static uint8_t velawear_ble_percent_from_intensity(float intensity)
   384	{
   385	  if (intensity <= 0.0f)
   386	    {
   387	      return 0;
   388	    }
   389	
   390	  if (intensity >= 1.0f)
   391	    {
   392	      return 100;
   393	    }
   394	
   395	  return (uint8_t)(intensity * 100.0f);
   396	}
