   403	int velawear_ble_publish_agent_event(const velawear_event_t *event)
   404	{
   405	  velawear_agent_event_t agent_event;
   406	  uint8_t frame[VELAWEAR_AGENT_EVENT_FRAME_SIZE];
   407	  int ret;
   408	
   409	  if (event == NULL || !g_initialized)
   410	    {
   411	      return VELAWEAR_ERR_INVAL;
   412	    }
   413	
   414	  memset(&agent_event, 0, sizeof(agent_event));
   415	  switch (event->type)
   416	    {
   417	      case VELAWEAR_EVENT_MOTION:
   418	        agent_event.event_type = VELAWEAR_AGENT_EVENT_MOTION;
   419	        agent_event.intensity_percent =
   420	            velawear_ble_percent_from_intensity(event->data.motion.intensity);
   421	        break;
   422	
   423	      case VELAWEAR_EVENT_FALL:
   424	        agent_event.event_type = VELAWEAR_AGENT_EVENT_FALL;
   425	        agent_event.priority = VELAWEAR_AGENT_PRIORITY_CRITICAL;
   426	        agent_event.intensity_percent = 100;
   427	        break;
   428	
   429	      case VELAWEAR_EVENT_AUDIO:
   430	        agent_event.event_type = VELAWEAR_AGENT_EVENT_AUDIO;
   431	        agent_event.intensity_percent = event->data.audio.active ? 100 : 0;
   432	        agent_event.value = velawear_ble_u16_saturate(event->data.audio.avg_abs);
   433	        agent_event.peak = velawear_ble_u16_saturate(event->data.audio.peak_abs);
   434	        if (event->data.audio.active)
   435	          {
   436	            agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ACTIVE;
   437	          }
   438	        break;
   439	
   440	      case VELAWEAR_EVENT_TIMER:
   441	        agent_event.event_type = VELAWEAR_AGENT_EVENT_SEDENTARY;
   442	        break;
   443	
   444	      default:
   445	        return VELAWEAR_ERR_NOSUPPORT;
   446	    }
   447	
   448	  pthread_mutex_lock(&g_lock);
   449	  agent_event.sequence = g_agent_event_sequence++;
   450	  if (g_alert_active)
   451	    {
   452	      agent_event.flags |= VELAWEAR_AGENT_EVENT_FLAG_ALERT;
   453	    }
   454	
   455	  ret = velawear_agent_encode_event(&agent_event, frame, sizeof(frame));
   456	  pthread_mutex_unlock(&g_lock);
   457	  if (ret < 0)
   458	    {
   459	      return ret;
   460	    }
