              stream_has_samples = true;
              start_ms = now_ms;
              active_streak = 0;
              silent_streak = 0;
              audio->level_active = false;
            }

          previous_active = audio->level_active;
          current_active = previous_active;

          if (!previous_active)
            {
              silent_streak = 0;
              if (avg_abs >= AUDIO_LEVEL_START_THRESHOLD)
                {
                  active_streak++;
                }
              else
